create table products (id varchar(40) primary key, sku varchar(80) not null unique, name varchar(200) not null, category varchar(40) not null, current_price decimal(12,2) not null, stock_level int not null, reorder_threshold int not null, demand_velocity decimal(12,2) not null, status varchar(40) not null, version bigint not null default 0, created_at timestamp not null, updated_at timestamp not null);
create table pricing_suggestions (id char(36) primary key, product_id varchar(40) not null, trigger_reason varchar(40) not null, current_price decimal(12,2) not null, recommended_price decimal(12,2) not null, direction varchar(20) not null, confidence decimal(4,3) not null, reasoning varchar(2000) not null, strategy_name varchar(80) not null, status varchar(20) not null, created_at timestamp not null, reviewed_at timestamp null, reviewed_by varchar(120), failure_reason varchar(500), constraint fk_pricing_product foreign key (product_id) references products(id));
create table reorder_suggestions (id char(36) primary key, product_id varchar(40) not null, trigger_reason varchar(40) not null, current_stock int not null, reorder_threshold int not null, recommended_quantity int not null, confidence decimal(4,3) not null, reasoning varchar(2000) not null, strategy_name varchar(80) not null, status varchar(20) not null, created_at timestamp not null, reviewed_at timestamp null, reviewed_by varchar(120), failure_reason varchar(500), constraint fk_reorder_product foreign key (product_id) references products(id));
create index idx_ps_product_status on pricing_suggestions(product_id,status); create index idx_rs_product_status on reorder_suggestions(product_id,status);
create table inventory_snapshots (id char(36) primary key, product_id varchar(40) not null, stock_level int not null, demand_velocity decimal(12,2) not null, recorded_at timestamp not null, source varchar(80) not null, constraint fk_snapshot_product foreign key (product_id) references products(id));